def two_sum_sorted(values, target):
    left = 0
    right = len(values) - 1
    while left < right:
        total = values[left] + values[right]
        if total == target:
            return left, right
        if total < target:
            left = left + 1
        else:
            right = right - 1
    return None

print(two_sum_sorted([1, 2, 4, 7], 6))
print(two_sum_sorted([2, 2], 4))
print(two_sum_sorted([2], 4))

def find_window(values, target):
    left = 0
    total = 0
    for right, value in enumerate(values):
        total = total + value
        while left <= right and total > target:
            total = total - values[left]
            left = left + 1
        if left <= right and total == target:
            return left, right + 1
    return None

for values in [[1, 0], [0, 0], []]:
    print(find_window(values, 0))
